import { Reporter } from './reporter';
import type { RunLocation } from '../services/abstract-check-runner';
import { Check } from '../constructs/check';
export type checkFilesMap = Map<string, Map<string, {
    check?: Check;
    result?: any;
    titleString: string;
}>>;
export default abstract class AbstractListReporter implements Reporter {
    _clearString: string;
    runLocation: RunLocation;
    checkFilesMap: checkFilesMap;
    numChecks: number;
    verbose: boolean;
    testSessionId?: string;
    testResultIds?: {
        [key: string]: string;
    };
    constructor(runLocation: RunLocation, checks: Array<Check>, verbose: boolean);
    abstract onBeginStatic(): void;
    abstract onBegin(testSessionId: string, testResultIds?: {
        [key: string]: string;
    }): void;
    abstract onEnd(): void;
    onCheckEnd(checkResult: any): void;
    onError(err: Error): void;
    _setTestSessionId(testSessionId?: string): void;
    _setTestResultIds(testResultIds?: {
        [key: string]: string;
    }): void;
    _clearSummary(): void;
    _printSummary(opts?: {
        skipCheckCount?: boolean;
    }): void;
    _printBriefSummary(): void;
    _printTestSessionsUrl(): void;
    _runLocationString(): string;
}
